<script setup lang="ts">
import{onMounted,reactive,ref}from'vue'
import{ElMessage}from'element-plus'
import{createUser,getDepartmentsAdmin,getUsers,updateUser,type ManagedUser}from'../../services/admin'
import type{Department}from'../../types/medical'
const rows=ref<ManagedUser[]>([]),departments=ref<Department[]>([]),loading=ref(false),dialog=ref(false),saving=ref(false),keyword=ref('')
const form=reactive({username:'',full_name:'',password:'',role:'doctor',phone:'',email:'',department_id:undefined as number|undefined,title:'',specialty:''})
function errorText(e:any,fallback:string){const errors=e.response?.data?.errors;if(errors){const first=Object.values(errors)[0] as string|string[]|undefined;if(first)return Array.isArray(first)?first.join('；'):String(first)}return e.response?.data?.detail||fallback}
async function load(){loading.value=true;try{const data=await getUsers({search:keyword.value});rows.value=data.results}catch{rows.value=[]}finally{loading.value=false}}
async function open(){Object.assign(form,{username:'',full_name:'',password:'',role:'doctor',phone:'',email:'',department_id:undefined,title:'',specialty:''});dialog.value=true;if(!departments.value.length)departments.value=(await getDepartmentsAdmin()).results.filter(item=>item.status==='active')}
async function submit(){if(!form.username.trim()||!form.full_name.trim()||!form.password){ElMessage.warning('请完整填写账号、姓名和密码');return}if(form.role==='doctor'&&!form.department_id){ElMessage.warning('医师必须选择科室');return}const payload={username:form.username.trim(),full_name:form.full_name.trim(),password:form.password,role:form.role,phone:form.phone.trim(),email:form.email.trim(),...(form.role==='doctor'?{department_id:form.department_id,title:form.title.trim(),specialty:form.specialty.trim()}:{})};saving.value=true;try{const created=await createUser(payload);ElMessage.success(created.doctor_no?`医师创建成功，编号 ${created.doctor_no}`:'账户创建成功');dialog.value=false;await load()}catch(e:any){ElMessage.error(errorText(e,'创建失败'))}finally{saving.value=false}}
async function toggle(row:ManagedUser){try{await updateUser(row.id,{is_active:!row.is_active});ElMessage.success(row.is_active?'账户已禁用':'账户已启用');await load()}catch{ElMessage.error('状态更新失败')}}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">ACCOUNT MANAGEMENT</p><h1>用户账户</h1><p>创建医师或患者账号，管理账户启用状态</p></div><el-button type="primary" @click="open">＋ 创建账户</el-button></div><el-card class="table-card"><div class="table-tools"><el-input v-model="keyword" placeholder="搜索用户名、姓名或手机号" clearable @keyup.enter="load"/><el-button @click="load">查询</el-button></div><el-table v-loading="loading" :data="rows"><el-table-column prop="username" label="用户名"/><el-table-column prop="full_name" label="姓名"/><el-table-column prop="role_display" label="角色"/><el-table-column prop="doctor_no" label="医师编号"><template #default="{row}">{{row.doctor_no||'—'}}</template></el-table-column><el-table-column prop="department_name" label="所属科室"><template #default="{row}">{{row.department_name||'—'}}</template></el-table-column><el-table-column prop="phone" label="手机号"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.is_active?'success':'info'">{{row.is_active_display}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link :type="row.is_active?'danger':'success'" @click="toggle(row)">{{row.is_active?'禁用':'启用'}}</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" title="创建业务账户" width="min(620px,94vw)"><el-form label-position="top"><el-row :gutter="14"><el-col :span="12"><el-form-item label="姓名" required><el-input v-model="form.full_name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="角色" required><el-select v-model="form.role" style="width:100%"><el-option label="医师" value="doctor"/><el-option label="患者" value="patient"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="用户名" required><el-input v-model="form.username"/></el-form-item></el-col><el-col :span="12"><el-form-item label="初始密码" required><el-input v-model="form.password" type="password" show-password/></el-form-item></el-col><el-col :span="12"><el-form-item label="手机号"><el-input v-model="form.phone"/></el-form-item></el-col><el-col :span="12"><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item></el-col><template v-if="form.role==='doctor'"><el-col :span="12"><el-form-item label="所属科室" required><el-select v-model="form.department_id" style="width:100%"><el-option v-for="item in departments" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="职称"><el-input v-model="form.title"/></el-form-item></el-col><el-col :span="24"><el-form-item label="专业方向"><el-input v-model="form.specialty"/></el-form-item></el-col></template></el-row></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">创建账户</el-button></template></el-dialog></section></template>
